head.script:
scwin.gDepCd = js_dep_cd;
scwin.gUpDepCd = js_belngdepcd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listDisclosureCountStatistics();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26400.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name rdo_QuaOrMM_onselchange
 * @description rdo_QuaOrMM onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_QuaOrMM_onselchange = function() {
    try {
        scwin.switchSel();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26400.rdo_QuaOrMM_onselchange" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        const CURR_YYYY = dts_Grid.getCellData(1, "CURR_YYYY");
        const PREV_YYYY = dts_Grid.getCellData(1, "PREV_YYYY");
        $c.cm.setColumnProp(grd_Grid, "CURR_CNT", "name", CURR_YYYY + "년");
        $c.cm.setColumnProp(grd_Grid, "PREV_CNT", "name", PREV_YYYY + "년");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26400.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26400.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave('ULDSTF26400.xml', SCREN_PROCS_TP_CD_07);
        let today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        let xls_path = $c.session.getExcelDownPath() + today + "_공시건수통계.xlsx";
        if (rdo_year_type.getValue() === '1') {
            $c.data.downloadGridViewOffice(grd_Grid, "공시건수통계", xls_path, 8, 0);
        } else {
            await scwin.excel();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26400.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_Excel_OnLoadCompleted
 * @description dts_Excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Excel_OnLoadCompleted = function(rowcount) {
    try {
        let today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        let xls_path = $c.session.getExcelDownPath() + today + "_공시건수통계.xlsx";
        $c.data.downloadGridViewOffice(grd_Excel, "공시건수통계", xls_path, 8, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26400.dts_Excel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Excel_OnLoadError
 * @description dts_Excel 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
