///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name initPage
 * @description session 값을 control 에 binding 시키는 함수.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    /*
    	상위부서코드 재셋팅 : 2009.02.24
    	뒤에 3자리가 000이면 부서코드를 상위부서코드에 셋팅한다.
     */
    if (js_belngdepcd.substring(1, 4) === '000') {
        scwin.gUpDepCd = js_dep_cd;
    }
    if (js_market === "9") {
        rdo_MKT_ID.setValue("1");
        panel_mkt.show("");
    } else {
        rdo_MKT_ID.setValue(js_market);
        panel_mkt.hide();

        // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            panel_dep_emp.show("");
            scwin.gDepCd = "UPTEAM";
        } else {
            panel_dep_emp.hide();
        }
        scwin.setHeadTitle(); // 년도 선택시 '숫자연도'로 표시, 기간선택시는 '당해'로 표시

    }
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert(gLdMktTp);

    const sbmOptions2 = {
        id : "sbm_dts_FormUpclss",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_FormUpclss=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let url = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=FISCYY_TP_CD";
    // dts_FISCYY_TP_CD.DataID = url;
    // dts_FISCYY_TP_CD.Reset();

    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= 1980; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_YYYY.CBData = str;
    str = "^전체,";
    for (let i = 1; i <= 12; i++) {
        str += $c.ut.lpad(i, 2, "0") + "^" + $c.ut.lpad(i, 2, "0") + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_MM.CBData = str;
    if (js_market === "9") {

    } else {
        rdo_MKT_ID.setValue(js_market);
        rdo_MKT_ID.setDisabled(true);
    }

    // 회사속성 콤보박스 초기화
    const sbmOptions = {
        id : "sbm_dts_COMPANY_ATTRIBUTE",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_COMPANY_ATTRIBUTE=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

