///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name switchSel
 * @description switch Sel 처리
 * @returns {void}
 * @hidden N
 */
scwin.switchSel = function() {
    const arr = new Array(cmb_FISCYY_TP_CD, cmb_MM);
    const a = rdo_QuaOrMM.getValue();
    const b = (a === 0) ? 1 : 0;
    arr[b].setValue("");
    arr[a].setDisabled(false);
    arr[b].setDisabled(true);
};

/**
 * @method
 * @name changGridHeader
 * @description chang Grid Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.changGridHeader = function() {
    if (rdo_year_type.getValue() === '1') {
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Show', false);
    }
};

/**
 * @method
 * @name checkBeforSearch
 * @description 언어구분 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBeforSearch = async function() {
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) === 0 && scwin.getChkValue(chb_eng_yn) === 0) {
        await $c.win.alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return false;
    }
    scwin.gDepCd = cmb_TeamList.getValue();
    const vF = chb_F.getValue();
    const vM = chb_M.getValue();
    const vA = chb_A.getValue();
    const vU = chb_U.getValue();
    if (vF === "N" && vM === "N" && vA === "N" && vU === "N") {
        chb_F.setValue("Y");
        chb_M.setValue("Y");
    }
    return true;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_mkt.hide();
    grd_Excel.hide();
};

/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};

/**
 * @method
 * @name setHeadTitle
 * @description set Head Title 처리
 * @returns {void}
 * @hidden N
 */
scwin.setHeadTitle = function() {
    if (rdo_year_type.getValue() === '1') {
        curryear = cmb_YYYY.getValue();
        lastyear = curryear - 1;
        $c.cm.setColumnProp(grd_Grid, 'currYear', 'Name', curryear + "년");
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Name', lastyear + "년");
    } else {
        $c.cm.setColumnProp(grd_Grid, 'currYear', 'Name', "당해");
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Name', "전해");
    }
};
